        public string EvolvesTo;  // 진화하면 무엇이 되는지(키). 진화 안 하면 null
        public bool Bounce;       // 걸을 때 프로그램이 살짝 띄워 줄지
        public int IdleMs;        // 대기 애니메이션이 원본에서 한 바퀴 돌던 시간(ms)
        public Dictionary<char, string> Palette;
